CREATE TABLE users(id integer primary key autoincrement,email text not null unique,password_hash text not null,name text not null,role text not null default 'editor',avatar text,status text not null default 'active',created_at text not null,updated_at text not null);
CREATE TABLE sessions(id text primary key,user_id integer not null references users(id),expires_at text not null,created_at text not null);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE authors(id integer primary key autoincrement,name text not null,slug text not null unique,bio text,avatar text,website text,social_links text,created_at text not null,updated_at text not null);
CREATE TABLE categories(id integer primary key autoincrement,name text not null,slug text not null unique,description text,parent_id integer,seo_title text,seo_description text,created_at text not null,updated_at text not null);
CREATE TABLE tags(id integer primary key autoincrement,name text not null,slug text not null unique,description text,seo_title text,seo_description text,created_at text not null,updated_at text not null);
CREATE TABLE developers(id integer primary key autoincrement,name text not null,slug text not null unique,description text,logo text,website text,seo_title text,seo_description text);
CREATE TABLE publishers(id integer primary key autoincrement,name text not null,slug text not null unique,description text,logo text,website text,seo_title text,seo_description text);
CREATE TABLE platforms(id integer primary key autoincrement,name text not null,slug text not null unique,description text,logo text,seo_title text,seo_description text);
CREATE TABLE games(id integer primary key autoincrement,name text not null,slug text not null unique,description text,cover_image text,cover_image_alt text,release_date text,genre text,developer_id integer references developers(id),publisher_id integer references publishers(id),official_website text,seo_title text,seo_description text,created_at text not null,updated_at text not null);
CREATE INDEX games_developer_idx ON games(developer_id); CREATE INDEX games_publisher_idx ON games(publisher_id);
CREATE TABLE game_platforms(game_id integer not null references games(id),platform_id integer not null references platforms(id),primary key(game_id,platform_id));
CREATE TABLE articles(id integer primary key autoincrement,title text not null,slug text not null unique,excerpt text not null,content text not null,hero_image text,hero_image_alt text,author_id integer references authors(id),category_id integer references categories(id),game_id integer references games(id),status text not null default 'draft',published_at text,scheduled_at text,created_at text not null,updated_at text not null,reading_time integer default 1,featured integer default 0,trending integer default 0,seo_title text,seo_description text,canonical_url text,og_image text,allow_indexing integer default 1);
CREATE INDEX articles_status_idx ON articles(status); CREATE INDEX articles_published_idx ON articles(published_at); CREATE INDEX articles_category_idx ON articles(category_id); CREATE INDEX articles_author_idx ON articles(author_id); CREATE INDEX articles_featured_idx ON articles(featured); CREATE INDEX articles_trending_idx ON articles(trending);
CREATE TABLE article_tags(article_id integer not null references articles(id),tag_id integer not null references tags(id),primary key(article_id,tag_id));
CREATE TABLE article_redirects(id integer primary key autoincrement,old_slug text not null unique,new_slug text not null,created_at text not null);
CREATE TABLE reviews(id integer primary key autoincrement,article_id integer references articles(id),game_id integer references games(id),score real,verdict text,pros text,cons text,platform text,created_at text not null,updated_at text not null); CREATE INDEX reviews_game_idx ON reviews(game_id);
CREATE TABLE guides(id integer primary key autoincrement,title text not null,slug text not null unique,content text not null,excerpt text,hero_image text,game_id integer references games(id),author_id integer references authors(id),category text,status text not null default 'draft',published_at text,updated_at text not null,seo_title text,seo_description text,canonical_url text);
CREATE TABLE newsletter_issues(id integer primary key autoincrement,issue_number integer not null,title text not null,slug text not null unique,description text,content text,hero_image text,status text not null default 'draft',published_at text,created_at text not null,updated_at text not null,seo_title text,seo_description text);
CREATE TABLE newsletter_subscribers(id integer primary key autoincrement,email text not null unique,name text,status text not null default 'active',source text,subscribed_at text,unsubscribed_at text,created_at text not null);
CREATE TABLE media(id integer primary key autoincrement,filename text not null,original_name text not null,url text not null,r2_key text not null,mime_type text not null,width integer,height integer,size integer,alt_text text,caption text,uploaded_by integer references users(id),created_at text not null);
CREATE TABLE audit_log(id integer primary key autoincrement,user_id integer,action text not null,entity text not null,entity_id text,created_at text not null);
